async function api(path,options={}){const response=await fetch(path,{headers:{'Content-Type':'application/json'},...options});const contentType=response.headers.get('content-type')||'';const data=contentType.includes('json')?await response.json():await response.blob();if(!response.ok){if(response.status===502)$('#connection-status').textContent='REDCap save failed - retry required';throw new Error(data.error||`Request failed (${response.status})`)}if(data?.redcap_save)$('#connection-status').textContent=data.redcap_save.temporary?'Test Country: temporary only - not saved to REDCap':`Saved to REDCap ${new Date(data.redcap_save.saved_at).toLocaleTimeString()}`;return data}
function scheduleRedcapSync(){clearTimeout(state.redcapSyncTimer);state.redcapSyncTimer=setTimeout(async()=>{try{const response=await fetch('/api/redcap/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(response.ok){const result=await response.json();$('#connection-status').textContent=`REDCap synced ${result.synced_at}`;return}const error=await response.json();if(!/token first|not configured/i.test(error.error||''))$('#connection-status').textContent='Saved locally · REDCap sync pending'}catch{$('#connection-status').textContent='Saved locally · REDCap sync pending'}},1200)}
