function entryControl(attr,key,type,options,value){const common=`data-${attr}="${key}" aria-label="${key.replaceAll('_',' ')}"`;if(type==='select'){const choices=String(value||'')&&!options.includes(String(value))?[...options,String(value)]:options;return `<select ${common}>${choices.map(o=>`<option value="${escapeHtml(o)}" ${String(value||'')===o?'selected':''}>${escapeHtml(o||'No response')}</option>`).join('')}</select>`}if(type==='multi')return multiControl(attr,key,options,value);if(type==='textarea')return `<textarea ${common} rows="3" placeholder="Add relevant details…">${escapeHtml(value||'')}</textarea>`;return `<input ${common} value="${escapeHtml(value||'')}" placeholder="Enter ${escapeHtml(key.replaceAll('_',' '))}">`}

