async function switchCountryProject(projectId){if(!projectId)return;if(state.workspaceSelected&&Number(projectId)===Number(state.projects?.active_project_id))return;const project=state.projects.projects.find(item=>item.id===Number(projectId));if(!project||!confirm(`Open ${project.country_name} (${project.reporting_period})? Unsaved browser changes will be discarded and active clerk sessions for the current country will end.`)){renderCountryProjects();return}try{await api('/api/projects/switch',{method:'POST',body:JSON.stringify({project_id:Number(projectId)})});state.workspaceSelected=true;state.workspaceSource=project.source||null;state.inventoryIndex=0;state.phase2Index=0;state.inventoryGroupId=null;state.profilingGroupId=null;state.domainId=null;await loadState(false);switchView('phase1');toast(`Opened ${project.country_name} assessment`)}catch(error){toast(error.message);alert(error.message);renderCountryProjects()}}
async function refreshCountryProjects(automatic=false){if(!hasCoordinatorAccess()||state.importInProgress)return;try{const latest=await api('/api/projects'),activeChanged=Number(latest.active_project_id)!==Number(state.projects?.active_project_id),listChanged=JSON.stringify(latest.projects.map(item=>[item.id,item.country_name,item.reporting_period]))!==JSON.stringify((state.projects?.projects||[]).map(item=>[item.id,item.country_name,item.reporting_period]));if(activeChanged){state.inventoryIndex=0;state.phase2Index=0;state.inventoryGroupId=null;state.profilingGroupId=null;state.domainId=null;await loadState(false);switchView('phase1');toast('Country assessment refreshed')}else{state.projects=latest;renderCountryProjects();if(listChanged||!automatic)toast('Country list refreshed')}}catch(error){if(!automatic)toast(error.message)}}

