function multiValueKey(value){return String(value||'').trim().toLocaleLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function normalizeMultiSelections(key,options,value){const values=Array.isArray(value)?value:String(value||'').split(/\s*[;,\n]\s*/).filter(Boolean),canonical=new Map(options.map(option=>[multiValueKey(option),option])),aliases={platforms:{'kobo':'Kobo system','kobotool':'Kobo system','kobotoolbox':'Kobo system'},system_type:{'event based surveillance data':'Event-based Surveillance'},surveillance_functions:{'idsr':'IDSR/weekly syndromic surveillance','weekly syndromic veillance':'IDSR/weekly syndromic surveillance','weekly syndromic surveillance':'IDSR/weekly syndromic surveillance','idsr weekly syndromic veillance':'IDSR/weekly syndromic surveillance','idsr weekly syndromic surveillance':'IDSR/weekly syndromic surveillance'},diseases_supported:{'ebola':'Ebola virus disease','ebola bundibugyo virus disease':'Ebola virus disease','bundibugyo':'Ebola virus disease','bundibugyo virus disease':'Ebola virus disease','marburg':'Marburg virus disease','yellow fever':'Yellow fever','polio':'Acute flaccid paralysis (AFP)/Polio','acute flaccid paralysis polio':'Acute flaccid paralysis (AFP)/Polio','influenza':'Influenza-like illness (ILI)','anthrax':'Human anthrax','other':'Other — specify','other specify':'Other — specify'},lab_results_received:{'csv upload':'CSV import'}}[key]||{};return [...new Set(values.map(value=>aliases[multiValueKey(value)]||canonical.get(multiValueKey(value))||String(value).trim()).filter(Boolean))]}
function profilingFieldOptions(key,options){const recorded=(state.profile?.phase2||[]).flatMap(item=>chartValues(item[key])),hasBlank=options.some(value=>value===''),choices=[...new Map([...options,...recorded].filter(value=>value!==''&&value!=null).map(value=>[multiValueKey(value),value])).values()];return hasBlank?['',...choices]:choices}
