function multiControl(attr,key,options,value){const selected=normalizeMultiSelections(key,options,value),custom=selected.filter(v=>!options.includes(v));return `<div class="multi-picker" data-${attr}="${key}">${options.map(o=>`<label class="check-option"><input type="checkbox" value="${escapeHtml(o)}" ${selected.includes(o)?'checked':''}>${escapeHtml(o)}</label>`).join('')}<input class="custom-multi" placeholder="Add another value; separate several with semicolons" value="${escapeHtml(custom.join('; '))}"></div>`}
function readMulti(container){const selected=[...container.querySelectorAll('input[type=checkbox]:checked')].map(x=>x.value);const custom=(container.querySelector('.custom-multi')?.value||'').split(/\s*[;,]\s*/).filter(Boolean);return [...new Set([...selected,...custom])]}
