function updateProfileProgress(markDirty=true){const groups=$$('#phase2-form .multi-picker[data-p2]');let total=0,done=0;p2Sections.flatMap(x=>x[1]).forEach(([key])=>{total++;const direct=$(`#phase2-form [data-p2="${key}"]:not(.multi-picker)`),multi=groups.find(x=>x.dataset.p2===key);if((direct&&isFilled(direct.value))||(multi&&readMulti(multi).length))done++});const pct=total?Math.round(done/total*100):0;$('#phase2-completion').textContent=`${pct}% complete`;$('#phase2-progress').style.width=`${pct}%`;if(markDirty){$('#save-phase2').textContent='Save changes';$('#save-phase2').classList.add('needs-save')}$$('.profile-section').forEach((section,i)=>{const fields=p2Sections[i][1],sectionDone=fields.filter(([key])=>{const direct=section.querySelector(`[data-p2="${key}"]:not(.multi-picker)`),multi=section.querySelector(`.multi-picker[data-p2="${key}"]`);return (direct&&isFilled(direct.value))||(multi&&readMulti(multi).length)}).length;section.querySelector('.completion-badge').textContent=`${sectionDone}/${fields.length}`})}
