async function selectDomain(domainId){const owner=assignment(domainId),coordinator=hasCoordinatorAccess()&&!state.groupId;if(coordinator){state.domainId=domainId;renderAll();requestAnimationFrame(()=>$$('textarea').forEach(autoGrow));return}if(owner&&owner.group_id!==Number(state.groupId)){toast(`Assigned to ${owner.group_name}. Select that group to view it.`);return}if(!owner){try{state.data=await api('/api/assign',{method:'POST',body:JSON.stringify({domain_id:domainId,group_id:Number(state.groupId)})});toast(`Domain assigned to ${currentGroup().name}`)}catch(error){toast(error.message);await loadState();return}}state.domainId=domainId;renderAll();requestAnimationFrame(()=>$$('textarea').forEach(autoGrow))}
function renderDomain(){const domain=domainById(state.domainId);if(!domain){$('#empty-domain').classList.remove('hidden');$('#domain-workspace').classList.add('hidden');return}$('#empty-domain').classList.add('hidden');$('#domain-workspace').classList.remove('hidden');const index=state.data.domains.findIndex(d=>d.id===domain.id)+1;const owner=assignment(domain.id);$('#domain-number').textContent=`DOMAIN ${index} OF 9`;$('#domain-title').textContent=domain.name;$('#domain-owner').textContent=owner?.group_name||'Unassigned';$('#release-domain').classList.toggle('hidden',!owner);const reassignSelect=$('#reassign-group'),canReassign=Boolean(owner&&state.data.groups.length>1);reassignSelect.innerHTML=state.data.groups.filter(g=>g.id!==owner?.group_id).map(g=>`<option value="${g.id}">${escapeHtml(g.name)}</option>`).join('');reassignSelect.classList.toggle('hidden',!canReassign);$('#reassign-domain').classList.toggle('hidden',!canReassign);$('#questions').innerHTML=domain.questions.map((q,i)=>questionHtml(q,i)).join('');bindQuestionInputs();updateProgress()}
function questionHtml(q,index){const saved=response(q.id),value=answerValue(saved),qid=q.source_id||q.id;let control='';if(q.type==='multi'){const selected=Array.isArray(value)?value:[];control=`<div class="multi-options">${q.options.map(option=>`<label class="check-option"><input type="checkbox" name="${q.id}" value="${escapeHtml(option)}" ${selected.includes(option)?'checked':''}>${escapeHtml(option)}</label>`).join('')}</div>`}else if(q.type==='select_explain'){control=`<select data-field="response"><option value="">Select a response</option>${q.options.map(option=>`<option ${value===option?'selected':''}>${escapeHtml(option)}</option>`).join('')}</select><label class="field-label">Explanation or supporting details <span class="optional-mark">Optional</span></label><textarea data-field="explanation" rows="2" placeholder="Add evidence, examples or context…">${escapeHtml(saved.explanation)}</textarea>`}else{control=`<textarea data-field="response" rows="3" placeholder="Enter a clear response. Include examples or evidence where possible.">${escapeHtml(value)}</textarea>`}return `<article class="question-card" data-question="${q.id}"><div class="question-count">Question ${index+1} of 5</div><p class="question-label"><span class="question-id">${qid.toUpperCase()}</span>${escapeHtml(q.text)}</p>${control}<details class="finding-details" ${saved.comment?'open':''}><summary>Add a gap, recommendation or comment <span>Optional</span></summary><label class="field-label">This information is used in the summary report</label><textarea class="comment-field" data-field="comment" rows="2" placeholder="Start with “Gap:” or “Recommendation:” to classify this finding.">${escapeHtml(saved.comment)}</textarea></details></article>`}
function bindQuestionInputs(){$$('#questions textarea').forEach(el=>{autoGrow(el);el.addEventListener('input',()=>{autoGrow(el);queueAutosave();updateProgress()})});$$('#questions select,#questions input').forEach(el=>el.addEventListener('change',()=>{queueAutosave();updateProgress()}))}
function collectResponses(){return $$('.question-card').map(card=>{const qid=card.dataset.question;const checks=[...card.querySelectorAll('input[type=checkbox]:checked')];const responseField=card.querySelector('[data-field=response]');return{question_id:qid,response:checks.length?checks.map(item=>item.value):(responseField?.value||''),explanation:card.querySelector('[data-field=explanation]')?.value||'',comment:card.querySelector('[data-field=comment]')?.value||''}})}
function updateProgress(){const items=collectResponses(),answered=items.filter(item=>Array.isArray(item.response)?item.response.length:String(item.response).trim()).length;$('#question-progress').textContent=`${answered} of 5 questions answered`;$('#domain-progress').style.width=`${answered*20}%`}
function queueAutosave(){clearTimeout(state.saveTimer);$('#save-state').textContent='Saving changes…';state.saveTimer=setTimeout(()=>saveDomain(true),900)}
async function saveDomain(silent=false){if(!state.domainId)return;const owner=assignment(state.domainId),targetGroup=Number(state.groupId||owner?.group_id)||null;if(!targetGroup){$('#save-state').textContent='Assign a group before entering responses';if(!silent)toast('Assign this domain to a group before saving responses');return}try{state.data=await api('/api/responses',{method:'POST',body:JSON.stringify({domain_id:state.domainId,group_id:targetGroup,responses:collectResponses()})});$('#save-state').textContent='All changes saved';renderDomains();renderDashboard();if(!silent)toast('Domain responses saved')}catch(error){$('#save-state').textContent='Save failed';toast(error.message)}}
async function addGroup(){const name=$('#new-group').value.trim();if(!name)return;try{state.data=await api('/api/groups',{method:'POST',body:JSON.stringify({name})});state.groupId=state.data.groups.at(-1).id;$('#new-group').value='';renderAll();toast('Group added')}catch(error){toast(error.message)}}
async function releaseDomain(){if(!state.domainId)return;if(!confirm('Release this domain so another group can claim it? Existing responses will remain.'))return;state.data=await api('/api/unassign',{method:'POST',body:JSON.stringify({domain_id:state.domainId})});state.domainId=null;renderAll();toast('Domain released')}
async function reassignDomain(){if(!state.domainId)return;const groupId=Number($('#reassign-group').value),group=state.data.groups.find(g=>g.id===groupId),domain=domainById(state.domainId);if(!group||!domain)return;if(!confirm(`Reassign ${domain.name} to ${group.name}? Existing responses will be retained.`))return;try{state.data=await api('/api/reassign',{method:'POST',body:JSON.stringify({domain_id:state.domainId,group_id:groupId})});state.groupId=groupId;renderAll();toast(`Domain reassigned to ${group.name}`)}catch(error){toast(error.message)}}
async function saveAssessment(){try{state.data=await api('/api/assessment',{method:'POST',body:JSON.stringify({title:$('#assessment-title').value,scope:$('#assessment-scope').value})});$('#save-state').textContent='All changes saved'}catch(error){toast(error.message)}}
async function importFiles(files){if(!files.length)return;$('#save-state').textContent='Importing Excel files…';const payload=[];for(const file of files){payload.push({name:file.name,data:await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.readAsDataURL(file)})})}try{const result=await api('/api/import',{method:'POST',body:JSON.stringify({files:payload,group_id:Number(state.groupId)})});state.data=result.state;renderAll();toast(`Imported ${result.imported} populated question records`)}catch(error){toast(error.message)}finally{$('#excel-files').value='';$('#save-state').textContent='All changes saved'}}
function renderDashboard(){if(!state.data)return;const domains=state.data.domains;const answered=domains.reduce((sum,d)=>sum+completed(d),0);const assigned=state.data.assignments.length;const completedDomains=domains.filter(d=>completed(d)===5).length;const findings=state.data.responses.filter(r=>r.comment.trim()).length;$('#metrics').innerHTML=[[assigned,'Domains assigned'],[completedDomains,'Domains complete'],[answered,'Questions answered'],[findings,'Recorded findings']].map(([value,label])=>`<article class="metric card"><strong>${value}</strong><span>${label}</span></article>`).join('');$('#domain-chart').innerHTML=domains.map(d=>barRow(d.name,completed(d)*20,`${completed(d)}/5`)).join('');$('#group-chart').innerHTML=state.data.groups.map(g=>{const owned=state.data.assignments.filter(a=>a.group_id===g.id).map(a=>domainById(a.domain_id));const total=owned.length*5,done=owned.reduce((sum,d)=>sum+completed(d),0);return barRow(g.name,total?done/total*100:0,`${done}/${total}`)}).join('');$('#status-table').innerHTML=domains.map(d=>{const owner=assignment(d.id),done=completed(d),updates=state.data.responses.filter(r=>r.domain_id===d.id).map(r=>r.updated_at).sort();return `<tr><td>${escapeHtml(d.name)}</td><td>${escapeHtml(owner?.group_name||'Unassigned')}</td><td>${done}/5</td><td>${done*20}%</td><td>${updates.at(-1)?new Date(updates.at(-1)).toLocaleString():'—'}</td></tr>`}).join('')}
function barRow(label,percent,value,index=0){return `<div class="bar-row"><span class="bar-label">${escapeHtml(label)}</span><span class="bar-track"><span class="bar-fill palette-${index%5}" style="width:${Math.max(0,Math.min(100,percent))}%"></span></span><span class="bar-value">${value}</span></div>`}
async function renderReport(){try{const report=await api('/api/report');$('#report-summary').innerHTML=report.sections.map(section=>`<article class="report-domain card"><h3>${escapeHtml(section.domain)}</h3><p class="report-meta">Assigned group: ${escapeHtml(section.group)}</p><div class="report-columns"><div class="report-block"><h4>Gaps</h4>${listOrEmpty(section.gaps.concat(section.other))}</div><div class="report-block recommendations"><h4>Recommendations</h4>${listOrEmpty(section.recommendations)}</div></div></article>`).join('')}catch(error){toast(error.message)}}
function savedValue(value){return Array.isArray(value)?value.join(', '):String(value??'')}
function savedFieldsHtml(record,fields){const rows=fields.filter(([key])=>isFilled(record?.[key])||isFilled(record?.field_comments?.[key])).map(([key,label])=>{const response=isFilled(record?.[key])?escapeHtml(savedValue(record[key])):'<span class="muted">No response</span>',comment=record?.field_comments?.[key]||(key==='data_exchange'?record?.exchange_comments:'');return `<tr><th>${escapeHtml(label)}</th><td>${response}${isFilled(comment)?`<div class="saved-question-comment"><strong>Comment:</strong> ${escapeHtml(comment)}</div>`:''}</td></tr>`}).join('');return rows?`<div class="table-wrap"><table><tbody>${rows}</tbody></table></div>`:'<p class="empty-note">No responses have been saved for this item.</p>'}
function renderSelectedAnalysis(result){const target=$('#full-report'),title={inventory:'Inventory',profiling:'Profiling',gap:'Gap Analysis'}[result.section],header=`<header class="report-hero"><h2>${escapeHtml(title)} Report</h2><div class="report-meta-grid"><span class="report-meta-chip">${escapeHtml(result.country_name)}</span><span class="report-meta-chip">${escapeHtml(result.reporting_period)}</span></div></header>`;let body='';if(result.section==='inventory'){const tools=result.inventory?.tools||[];body=tools.map((tool,index)=>`<article class="card phase-card"><h3>${index+1}. ${escapeHtml(tool.inventory_name||'Unnamed system')}</h3>${savedFieldsHtml(tool,p1Fields)}</article>`).join('')||'<article class="card phase-card"><p class="empty-note">No Inventory systems were recorded.</p></article>'}else if(result.section==='profiling'){const profiles=result.profiling||[],fields=p2Sections.flatMap(section=>section[1]);body=profiles.map((profile,index)=>`<article class="card phase-card"><h3>${index+1}. ${escapeHtml(profile.official_name||'Unnamed system')}</h3>${savedFieldsHtml(profile,fields)}</article>`).join('')||'<article class="card phase-card"><p class="empty-note">No Profiling records were recorded.</p></article>'}else{const sections=result.gap?.sections||[];body=sections.map(section=>`<article class="report-domain card"><h3>${escapeHtml(section.domain)}</h3><p class="report-meta">Assigned group: ${escapeHtml(section.group||'Unassigned')}</p><div class="report-columns"><div class="report-block"><h4>Gaps and other findings</h4>${listOrEmpty([...(section.gaps||[]),...(section.other||[])])}</div><div class="report-block recommendations"><h4>Recommendations</h4>${listOrEmpty(section.recommendations||[])}</div></div></article>`).join('')||'<article class="card phase-card"><p class="empty-note">No Gap Analysis findings were recorded.</p></article>'}target.innerHTML=header+body}
function toggleReportAssistant(open=!$('#assistant-panel').classList.contains('hidden')){const panel=$('#assistant-panel'),expanded=Boolean(open);panel.classList.toggle('hidden',!expanded);$('#assistant-toggle').setAttribute('aria-expanded',String(expanded));if(expanded&&!$('#assistant-question').disabled)setTimeout(()=>$('#assistant-question').focus(),0)}
function enableAssistantDragging(){const shell=$('#report-assistant'),launcher=$('#assistant-toggle'),handle=$('#assistant-drag-handle');let launcherDragged=false;function startDrag(event,fromLauncher=false){if(event.button!==0||(!fromLauncher&&event.target.closest('button')))return;const rect=shell.getBoundingClientRect(),offsetX=event.clientX-rect.left,offsetY=event.clientY-rect.top;let moved=false;shell.style.left=`${rect.left}px`;shell.style.top=`${rect.top}px`;shell.style.right='auto';shell.style.bottom='auto';const move=moveEvent=>{if(Math.abs(moveEvent.clientX-event.clientX)>3||Math.abs(moveEvent.clientY-event.clientY)>3)moved=true;const current=shell.getBoundingClientRect(),left=Math.max(8,Math.min(moveEvent.clientX-offsetX,window.innerWidth-current.width-8)),top=Math.max(8,Math.min(moveEvent.clientY-offsetY,window.innerHeight-current.height-8));shell.style.left=`${left}px`;shell.style.top=`${top}px`;moveEvent.preventDefault()};const stop=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop);if(fromLauncher&&moved)launcherDragged=true};window.addEventListener('pointermove',move,{passive:false});window.addEventListener('pointerup',stop,{once:true});if(!fromLauncher)event.preventDefault()}handle.addEventListener('pointerdown',event=>startDrag(event,false));launcher.addEventListener('pointerdown',event=>startDrag(event,true));launcher.onclick=()=>{if(launcherDragged){launcherDragged=false;return}toggleReportAssistant($('#assistant-panel').classList.contains('hidden'))};window.addEventListener('resize',()=>{if(!shell.style.left)return;const rect=shell.getBoundingClientRect();shell.style.left=`${Math.max(8,Math.min(rect.left,window.innerWidth-rect.width-8))}px`;shell.style.top=`${Math.max(8,Math.min(rect.top,window.innerHeight-rect.height-8))}px`})}
function enableAssistantResizing(){const shell=$('#report-assistant'),panel=$('#assistant-panel'),handle=$('#assistant-resize-handle'),launcher=$('#assistant-toggle');handle.addEventListener('pointerdown',event=>{if(event.button!==0)return;const shellRect=shell.getBoundingClientRect(),panelRect=panel.getBoundingClientRect(),startX=event.clientX,startY=event.clientY,startWidth=panelRect.width,startHeight=panelRect.height;shell.style.left=`${shellRect.left}px`;shell.style.top=`${shellRect.top}px`;shell.style.right='auto';shell.style.bottom='auto';const move=moveEvent=>{const launcherHeight=launcher.getBoundingClientRect().height,maxWidth=Math.max(320,window.innerWidth-shellRect.left-8),maxHeight=Math.max(330,window.innerHeight-shellRect.top-launcherHeight-18);panel.style.width=`${Math.max(320,Math.min(startWidth+moveEvent.clientX-startX,maxWidth))}px`;panel.style.height=`${Math.max(330,Math.min(startHeight+moveEvent.clientY-startY,maxHeight))}px`;moveEvent.preventDefault()};const stop=()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop)};window.addEventListener('pointermove',move,{passive:false});window.addEventListener('pointerup',stop,{once:true});event.preventDefault()})}
function setReportAssistantEnabled(enabled){state.recommendationAudit=null;$('#assistant-question').disabled=!enabled;$('#ask-report-assistant').disabled=!enabled;$('#assistant-toggle').classList.toggle('ready',enabled);$$('[data-assistant-prompt]').forEach(button=>button.disabled=!enabled);state.assistantHistory=[];state.assistantModelAvailable=false;$('#assistant-messages').innerHTML=enabled?'<div class="assistant-message-row assistant"><span class="message-avatar" aria-hidden="true">A</span><div class="assistant-message assistant"><span class="message-role">Report assistant</span>Hello. I can help you interpret this report. Ask about its Inventory, Profiling, Gap Analysis, findings, or recommendations.</div></div>':'<div class="assistant-empty"><strong>Generate a report to start</strong><span>I can discuss its Inventory, Profiling, or Gap Analysis findings.</span></div>';if(enabled)api('/api/assistant/status').then(status=>{state.assistantModelAvailable=Boolean(status.available);const label=$('.assistant-identity p');if(label)label.innerHTML=`<span class="assistant-status-dot"></span>${status.available?`Local AI · ${escapeHtml(status.model)}`:'Built-in assistant · Current report only'}`}).catch(()=>{})}
function reportSections(text){const headings=new Set(['Executive Summary','Profiling','Overview of the HIS Inventory','Summary of Findings','Recommendations','Assessment completeness','Domain capability scores','Identified gaps and risks','Strengths to retain','Prioritised recommendations','Action plan','Data-quality and consistency flags']);const sections={},lines=String(text||'').replace(/\r/g,'').split('\n');let current='Overview',domain='';for(let index=0;index<lines.length;index++){const line=lines[index].trim(),next=String(lines[index+1]||'').trim();if(!line)continue;if(next.startsWith('Assigned group:')){domain=line;continue}if(line.startsWith('Assigned group:'))continue;if(/^(Gaps|Gaps and other findings|Recommendations):$/.test(line)){current=`${line.replace(/:$/,'')}${domain?` - ${domain}`:''}`;sections[current]??=[];continue}if(headings.has(line)||/^Gap Analysis:/.test(line)){current=line;sections[current]??=[];continue}if(!line.startsWith('| ---'))(sections[current]??=[]).push(line.replace(/^[-•]\s+/,''))}return sections}
function reportProse(lines,paragraphCount){const sentences=lines.map(line=>String(line).replace(/^\d+[.)]\s*/, '').trim()).filter(Boolean).map(line=>/[.!?]$/.test(line)?line:`${line}.`);if(!sentences.length)return'';if(paragraphCount===1)return sentences.join(' ');const split=Math.ceil(sentences.length/2);return [sentences.slice(0,split).join(' '),sentences.slice(split).join(' ')].filter(Boolean).join('\n\n')}
function cleanReportLines(lines){return lines.map(line=>String(line).replace(/^\d+[.)]\s*/, '').trim()).filter(line=>line&&!line.startsWith('|')&&!/^(Country|Reporting Period|Assigned group):/.test(line)&&!/^No .* (recorded|identified|available)/i.test(line))}
function similarReportText(left,right){const words=text=>new Set(multiValueKey(text).split(' ').filter(word=>word.length>3)),a=words(left),b=words(right),common=[...a].filter(word=>b.has(word)).length,total=new Set([...a,...b]).size;return total?common/total>=.72:false}
function consolidateReportLines(lines){const unique=[];for(const line of cleanReportLines(lines)){if(!unique.some(saved=>multiValueKey(saved)===multiValueKey(line)||similarReportText(saved,line)))unique.push(line)}return unique}
function recommendationFromFinding(line){const clean=String(line).replace(/[.!?]+$/,'').trim(),text=clean.toLocaleLowerCase();if(/api/.test(text))return`Confirm API capability and develop an appropriate standards-based integration plan for the affected system.`;if(/exchange|interop|integrat|link/.test(text))return`Define and implement an interoperability plan addressing the documented system linkage or data-exchange gap.`;if(/access|coverage|offline|data entry|data-entry/.test(text))return`Validate the documented access limitation and implement a phased improvement plan for affected users and locations.`;if(/policy|govern|security|privacy|sop|manual/.test(text))return`Assign an accountable owner to address the documented governance, security, policy, or procedural gap.`;return`Review the documented gap and agree a corrective action, responsible owner, and completion date: ${clean}.`}
function recommendationLines(sections){const explicit=consolidateReportLines(Object.entries(sections).filter(([name])=>/recommend|prioriti|action/i.test(name)).flatMap(([,lines])=>lines));return explicit.length?explicit:consolidateReportLines(findingLines(sections).map(recommendationFromFinding))}
function findingLines(sections){return consolidateReportLines(Object.entries(sections).filter(([name])=>/executive|overview|inventory|profil|finding|gap|risk|quality|complete|capability/i.test(name)).flatMap(([,lines])=>lines))}
function recommendationPriority(line){const text=line.toLocaleLowerCase();if(/complete|confirm|document|validate|define|clarify|correct/.test(text))return['Immediate','0-3 months'];if(/review|assess|develop|establish|prioriti/.test(text))return['Short term','3-6 months'];return['Medium term','6-12 months']}
function recommendationOwner(line){const text=line.toLocaleLowerCase();if(/api|interop|integrat|exchange|link/.test(text))return'Digital health team and system owners';if(/access|coverage|facility|district|offline|data-entry|data entry/.test(text))return'Surveillance programme and subnational teams';if(/govern|policy|security|privacy|sop/.test(text))return'MoH/NPHI governance leads';return'Relevant system owner'}
function executiveSummary(sections){const findings=findingLines(sections).slice(0,5),recommendations=recommendationLines(sections).slice(0,4);if(!findings.length&&!recommendations.length)return'The generated report does not contain enough findings or recommendations for an executive summary.';const first=findings.length?`The assessment highlights ${findings.map(line=>line.replace(/[.!?]+$/,'')).join('; ')}.`:'The assessment report contains limited documented findings.';const second=recommendations.length?`Priority attention should focus on ${recommendations.map(line=>line.replace(/^(Review|Assess|Confirm|Document|Complete|Develop|Define)\s+/i,'').replace(/[.!?]+$/,'')).join('; ')}.`:'Further validation is required before priority actions can be defined.';return`${first}\n\n${second}`}
function prioritisedRecommendations(sections){const lines=recommendationLines(sections);if(!lines.length)return'The generated report contains no recommendations to prioritise.';const groups={'Immediate':[],'Short term':[],'Medium term':[]};lines.forEach(line=>groups[recommendationPriority(line)[0]].push(line));return Object.entries(groups).filter(([,items])=>items.length).map(([priority,items])=>`${priority}\n${items.map((line,index)=>`${index+1}. ${line}`).join('\n')}`).join('\n\n')}
function linkedPrioritisedRecommendations(sections){const recommendations=recommendationLines(sections).slice(0,8),findings=findingLines(sections);if(!recommendations.length)return'The generated report contains no recommendations to prioritise.';const words=value=>new Set(multiValueKey(value).split(' ').filter(word=>word.length>3));return recommendations.map((recommendation,index)=>{const recommendationWords=words(recommendation);let best='',score=0;for(const finding of findings){const findingWords=words(finding),union=new Set([...recommendationWords,...findingWords]).size,overlap=[...recommendationWords].filter(word=>findingWords.has(word)).length/Math.max(1,union);if(overlap>score){score=overlap;best=finding}}const priority=recommendationPriority(recommendation)[0];return`${index+1}. Recommendation: ${recommendation}\n   Supporting finding: ${best||'The generated report does not provide a sufficiently specific supporting finding; validate this action before adoption.'}\n   Evidence-to-action link: ${best?'The proposed action responds directly to the documented finding above.':'Evidence validation is required before implementation.'}\n   Priority: ${priority}`}).join('\n\n')+'\n\nSequencing note: Complete immediate validation and governance actions before dependent implementation and integration work.'}
function actionPlan(sections){const lines=recommendationLines(sections);if(!lines.length)return'The generated report contains no recommendations from which to create an action plan.';return lines.map((line,index)=>{const[priority,timeframe]=recommendationPriority(line);return`${index+1}. Action: ${line}\n   Priority: ${priority} | Suggested lead: ${recommendationOwner(line)} | Timeframe: ${timeframe}`}).join('\n\n')}
// Rule-based synthesis: evidence remains verbatim; proposed actions are not recorded facts.
function consolidatedReportOutput(sections,includeAudit=false){
  const themes=[
    ['Governance and coordination',/coordinat|policy|policies|govern|roles|responsibil|\bTOR\b|approval|transition of functions|leadership/i,'Agree institutional responsibilities, approval steps and coordination arrangements for the recorded gaps; maintain an action log and review unresolved decisions.','Track pending approvals and completion of agreed coordination actions.'],
    ['Sustainable financing',/fund|financ|budget|salary|salaries|incentive|donor|doner|donar/i,'Cost the documented operating needs, distinguish available funding from remaining gaps, and agree responsibilities for maintaining essential activities.','Track unfunded needs and interruptions to supported activities.'],
    ['Workforce and technical support',/train|knowledge|knowlege|expertise|skills|mentor|capacity|staff|help.?desk|technical support|rotation|workshop/i,'Identify the specific tasks staff cannot complete; provide practical coaching and accessible technical support, then verify task completion during follow-up.','Track demonstrated task completion and recurring support requests.'],
    ['Infrastructure and reporting continuity',/air\s*time|credit|data bundles|network|internet|offline|off.line|infrastr|power|equipment|devices|supplies|toolkits|procure|transport|insecurity|coverage|all the levels|digitalisation|digitalization|reporting tools/i,'Identify affected locations and essential equipment or connectivity needs; agree maintenance and operating support, and test alternative reporting procedures during outages.','Track service interruptions, reporting delays and unresolved equipment faults.'],
    ['System integration and transition',/interop|parallel|duplicat|data exchange|vertical reporting|DHIS2|transition to|phased out|phasing out|data architecture|data artichecture/i,'Map overlapping reporting requirements and functions that must be retained; agree authoritative data sources and validate exchange, reconciliation and replacement workflows before retiring any system.','Track duplicate entry requirements, reconciliation discrepancies and validated migration requirements.'],
    ['Surveillance configuration and data quality',/disease list|case definition|threshold|notifiable|mpox|missing data|data quality|formats|linelists|line lists|reporting formats/i,'Validate the reported configuration and data-quality gaps with responsible teams; approve required updates to definitions, reporting formats or checks, and verify corrected outputs before release.','Track validated gaps, completed configuration checks and unresolved data errors.'],
    ['Analysis, dissemination and feedback',/analy[st]|dashboard|situation report|feedback|disseminat|reports.*public/i,'Identify the analysis products and authorised audiences affected by the findings; agree production, distribution and feedback responsibilities and follow up on unresolved reporting needs.','Track availability of required products and completion of feedback actions.'],
    ['Data access, protection and recovery',/ownership|legal|privacy|access|portal|back.?up|security|sharing|register|audit trail|accountability/i,'Clarify who may access and share the affected data; document approved permissions and recovery arrangements, and verify them before expanding access. Public access must not be inferred from a respondent request.','Track unresolved access requests, permission reviews and recovery checks.']
  ];
  const evidence=[],suggestions=[],seen=new Set();
  const suggestionPattern=/^(?:we recommend|there (?:is a need|should)|provision of|provide\b|conduct\b|establish\b|strengthen\b|develop\b|train\b|allocate\b|improve\b|regular\/timely|frequent update|setting up|capacity building\b(?!.*(?:lack|limited|inadequate)))|\b(?:should|must|need to)\b/i;
  for(const [section,lines] of Object.entries(sections)){
    if(!/executive|overview|inventory|profil|finding|gap|risk|quality|complete|recommend|action|prioriti/i.test(section))continue;
    const explicit=/recommend|action|prioriti/i.test(section);
    for(const text of cleanReportLines(lines)){
      if(/^[\s\-–—.]+$/.test(text)||/^(?:N\/?A|none|not applicable|no other recommendation.*)$/i.test(text)||/^(?:Surveillance Profile Report|Consolidated findings|Consolidated recommendations|Executive Summary|Profiling|Recommendations|Summary of Findings)$/i.test(text))continue;
      const key=section+'|'+text.toLocaleLowerCase();if(seen.has(key))continue;seen.add(key);
      const item={text,section};
      if(explicit||suggestionPattern.test(text))suggestions.push(item);else evidence.push(item);
    }
  }
  if(!evidence.length&&!suggestions.length)return 'No substantive findings or respondent suggestions are available to consolidate.';
  const groups=themes.map(([name,pattern,action,indicator])=>({name,pattern,action,indicator,items:[]})),unmatched=[];
  evidence.forEach((item,index)=>{item.id=`F${index+1}`;let matched=false;for(const group of groups){if(group.pattern.test(item.text)){group.items.push(item);matched=true}}if(!matched)unmatched.push(item)});
  const output=['Consolidated evidence and proposed actions','Built-in synthesis of the supplied report. Evidence excerpts are respondent/report statements, not independently verified facts. Actions and monitoring measures below are proposed; owners, budgets and deadlines require agreement.'];
  for(const group of groups.filter(group=>group.items.length)){
    output.push(`${group.name}\nRecorded evidence (examples): ${group.items.slice(0,2).map(item=>`[${item.section}] ${item.text}`).join(' | ')}\nSupporting findings: ${group.items.map(item=>item.id).join(', ')}\nProposed action: ${group.action}\nProposed monitoring: ${group.indicator}`);
  }
  if(unmatched.length)output.push(`Findings requiring individual review: ${unmatched.map(item=>item.id).join(', ')}. These have been retained below; no automatic recommendation has been inferred.`);
  if(includeAudit&&evidence.length)output.push('Evidence register\n'+evidence.map(item=>`${item.id} [${item.section}]: ${item.text}`).join('\n'));
  if(includeAudit&&suggestions.length)output.push('Recorded suggestions — for review, not validated recommendations\n'+[...new Set(suggestions.map(item=>`[${item.section}]: ${item.text}`))].map((text,index)=>`S${index+1} ${text}`).join('\n'));
  if(includeAudit){
    const originals=Object.entries(sections).filter(([name])=>/recommend|action|prioriti/i.test(name)).flatMap(([section,lines])=>lines.filter(line=>String(line).trim()).map(line=>({section,text:String(line).trim()})));
    output.push('Original recommendation coverage check ? theme mapping requires review\n'+originals.map((item,index)=>{
      const text=item.text.replace(/^\d+[.)]\s*/,''),matched=groups.filter(group=>group.pattern.test(text));
      const status=/^[-??.\s]+$/.test(text)?'Excluded: placeholder, no recommendation.':/^no other recommendation/i.test(text)?'Context only: no additional action proposed; retain the stated transition qualification.':matched.length?'Related themes: '+matched.map(group=>group.name+(group.items.length?' (validate action coverage against the linked findings)':' (supporting evidence not identified)')).join('; '):'Unresolved: individual review required.';
      return `R${index+1} [${item.section}]: ${item.text}\n  ${status}`;
    }).join('\n'));
  }
  if(!includeAudit)output.push('A separate coverage check retains the detailed findings and recorded suggestions. Ask for a recommendation coverage check to review unresolved issues and theme mappings.');
  output.push('Review limitations: Theme matching uses wording, not clinical or technical validation. A finding may support more than one theme. Confirm applicability, contradictions and system-specific details before adopting any action.');
  return output.join('\n\n');
}
function localSectionReport(sections){const findings=findingLines(sections),recommendations=recommendationLines(sections);return`${executiveSummary(sections)}${findings.length?`\n\nKey findings\n${findings.slice(0,8).map((line,index)=>`${index+1}. ${line}`).join('\n')}`:''}${recommendations.length?`\n\nRecommendations\n${recommendations.slice(0,8).map((line,index)=>`${index+1}. ${line}`).join('\n')}`:''}`}
function localReportAnswer(question){const sections=reportSections(state.analysisReportText),query=String(question||'').trim().toLocaleLowerCase(),all=Object.entries(sections),recommendationRequest=/recommend|priority|action|should/.test(query);if(/coverage check|recommendation audit/.test(query))return consolidatedReportOutput(sections,true);if(/recommend|consolidat|group.*theme/.test(query))return consolidatedReportOutput(sections);if(/executive\s+summary/.test(query))return executiveSummary(sections);if(/consolidat|remove\s+(duplicate|repetition)|deduplicat|repetition/.test(query))return consolidatedReportOutput(sections);if(/action\s+plan/.test(query))return actionPlan(sections);if(/prioriti[sz]e.*recommend|recommend.*prioriti[sz]e|prioritised recommendation/.test(query))return prioritisedRecommendations(sections);if(/(produce|generate|draft|create).*(inventory|profil|gap|analysis).*report|(inventory|profil|gap|analysis).*report/.test(query))return localSectionReport(sections);let preferred=[];if(recommendationRequest)preferred=all.filter(([name])=>/recommend|prioriti|action/i.test(name));else if(/access|availab|coverage/.test(query))preferred=all.map(([name,lines])=>[name,lines.filter(line=>/access|availab|coverage|geograph|entry|user/i.test(line))]).filter(([,lines])=>lines.length);else if(/interop|integration|exchange|api|link/.test(query))preferred=all.map(([name,lines])=>[name,lines.filter(line=>/interop|integrat|exchange|api|link/i.test(line))]).filter(([,lines])=>lines.length);else if(/risk|gap|limitation|weak/.test(query))preferred=all.filter(([name])=>/finding|gap|risk|quality/i.test(name));else if(/score|capability|domain/.test(query))preferred=all.filter(([name])=>/capability/i.test(name));else if(/complete|missing/.test(query))preferred=all.filter(([name])=>/complete|quality/i.test(name));else preferred=all.filter(([name])=>/executive|finding|overview|inventory|profil/i.test(name));const items=preferred.flatMap(([name,lines])=>lines.filter(line=>line&&!/^(Country|Reporting Period):/.test(line)).map(line=>({name,line}))).filter(item=>!item.line.startsWith('| Domain |')&&!item.line.startsWith('| System |')).slice(0,8);if(!items.length)return 'The generated report does not contain enough information to answer that question. Try asking about Inventory, Profiling, Gap Analysis, findings, access limitations, interoperability, capability scores, priorities, or recommendations.';if(recommendationRequest&&/(one|1|single)\s+paragraph|paragraph\s+(one|1)|reduce.*paragraph/.test(query))return reportProse(items.map(item=>item.line),1);if(recommendationRequest&&/(two|2)\s+paragraph|paragraphs?\s+(two|2)/.test(query))return reportProse(items.map(item=>item.line),2);return items.map((item,index)=>`${index+1}. ${item.line}`).join('\n')}
async function streamAssistantAnswer(payload,onDelta){const response=await fetch('/api/assistant/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok){const error=await response.json().catch(()=>({}));throw new Error(error.error||`Local AI request failed (${response.status})`)}if(!response.body)throw new Error('Streaming is not supported by this browser');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',answer='';while(true){const{value,done}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split('\n');buffer=lines.pop()||'';for(const line of lines){if(!line.trim())continue;const packet=JSON.parse(line);if(packet.coverage_check)state.recommendationAudit=packet.coverage_check;if(packet.delta){answer+=packet.delta;onDelta(answer)}}if(done)break}if(buffer.trim()){const packet=JSON.parse(buffer);if(packet.coverage_check)state.recommendationAudit=packet.coverage_check;if(packet.delta){answer+=packet.delta;onDelta(answer)}}return answer.trim()}
