function renderFullReport(){if(!state.profile)return;const p1=state.profile.phase1||{},tools=(p1.tools||[]).filter(t=>t.inventory_name?.trim()),p2=(state.profile.phase2||[]).filter(a=>a.official_name?.trim()&&a.official_name.trim().toLowerCase()!=='unnamed');const types={};tools.forEach(t=>(Array.isArray(t.system_type)?t.system_type:[t.system_type]).filter(Boolean).forEach(v=>types[v]=(types[v]||0)+1));const completeness=p2.map(a=>{const keys=Object.keys(a).filter(k=>k!=='official_name'),filled=keys.filter(k=>Array.isArray(a[k])?a[k].length:String(a[k]||'').trim()).length;return[a.official_name,filled,keys.length,keys.length?Math.round(filled/keys.length*100):0]});const gaps=[],strengths=[],recs=[],actions=[];p2.forEach(a=>{const n=a.official_name;[['data_policy','no approved data policy is documented'],['security_controls','security and privacy controls are not implemented'],['sop_available','standard operating procedures are not available'],['user_manuals','user manuals or job aids are not available'],['data_exchange','data exchange with other systems is not supported'],['api_available','API access is not available']].forEach(([k,m])=>{if(String(a[k]||'').toLowerCase()==='no')gaps.push(`${n}: ${m}.`)});['known_limitations','operational_challenges'].forEach(k=>{if(String(a[k]||'').trim())gaps.push(`${n}: ${a[k]}`)});[['open_source','open source or open standards are available'],['api_available','API access is available'],['security_controls','security and privacy controls are in place'],['sop_available','standard operating procedures are available'],['user_manuals','user manuals or job aids are available']].forEach(([k,m])=>{if(String(a[k]||'').toLowerCase()==='yes')strengths.push(`${n}: ${m}.`)});if(String(a.retained_capabilities||'').trim())strengths.push(`${n}: ${a.retained_capabilities}`);String(a.priority_actions||'').split(/[;\n]/).filter(Boolean).forEach(x=>recs.push(`${n}: ${x.trim()}`));String(a.planned_enhancements||'').split(/[;\n]/).filter(Boolean).forEach(x=>actions.push(`${n}: ${x.trim()}`))});$('#full-report').innerHTML=`<article class="card phase-card"><h3>Phase 1: HIS Inventory</h3><p><strong>Country:</strong> ${escapeHtml(p1.country_name||'Not provided')} &nbsp; <strong>Reporting period:</strong> ${escapeHtml(p1.reporting_period||'Not provided')}</p><p><strong>Total systems:</strong> ${tools.length}</p><p><strong>System types:</strong> ${escapeHtml(Object.entries(types).map(([k,v])=>`${k} (${v})`).join(', ')||'None recorded')}</p><div class="table-wrap"><table><thead><tr><th>System</th><th>Responsible unit</th><th>Coverage</th><th>Technology</th><th>API</th></tr></thead><tbody>${tools.map(t=>`<tr><td>${escapeHtml(t.inventory_name)}</td><td>${escapeHtml(t.unit_responsible)}</td><td>${escapeHtml(t.geographical_coverage)}</td><td>${escapeHtml(t.technology)}</td><td>${escapeHtml(t.has_api)}</td></tr>`).join('')}</tbody></table></div></article><article class="card phase-card"><h3>Phase 2: System Assessment</h3><h4>Assessment completeness</h4><div class="table-wrap"><table><thead><tr><th>System</th><th>Completed</th><th>Total fields</th><th>Completeness</th></tr></thead><tbody>${completeness.map(r=>`<tr><td>${escapeHtml(r[0])}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}%</td></tr>`).join('')}</tbody></table></div><div class="report-columns"><div class="report-block"><h4>Identified gaps and risks</h4>${listOrEmpty(gaps)}<h4>Action plan</h4>${listOrEmpty(actions)}</div><div class="report-block recommendations"><h4>Strengths to retain</h4>${listOrEmpty(strengths)}<h4>Prioritised recommendations</h4>${listOrEmpty(recs)}</div></div></article>`}
