function counts(values){return values.reduce((out,value)=>{if(value)out[value]=(out[value]||0)+1;return out},{})}
function chartFromCounts(target,data,empty='No data recorded'){const entries=Object.entries(data).sort((a,b)=>b[1]-a[1]),max=Math.max(1,...entries.map(x=>x[1]));if(!entries.length){$(target).innerHTML=`<p class="empty-note">${empty}</p>`;return}const width=Math.max(560,entries.length*112),compact=entries.length<=4?' compact':'';$(target).innerHTML=`<div class="vertical-chart-scroll"><div class="vertical-chart${compact}" style="width:${width}px"><div class="chart-grid-lines"><span></span><span></span><span></span><span></span></div>${entries.map(([label,value],index)=>`<div class="vbar-item" title="${escapeHtml(label)}: ${value}"><span class="vbar-value">${value}</span><span class="vbar-column palette-${index%5}" style="height:${Math.max(10,Math.round(value/max*205))}px"></span><span class="vbar-label">${escapeHtml(label)}</span></div>`).join('')}</div></div>`}
function chartValues(value){return (Array.isArray(value)?value:[value]).flatMap(item=>String(item||'').split(/\s*[;,\n]\s*/)).map(item=>item.trim()).filter(Boolean)}
function renderPortfolioDashboard(profile=state.profile){const p1=profile?.phase1||{},tools=(p1.tools||[]).filter(t=>t.inventory_name?.trim()),p2=(profile?.phase2||[]).filter(a=>a.official_name?.trim());const typeValues=[],functions=[];tools.forEach(tool=>{chartValues(tool.system_type).forEach(x=>typeValues.push(x));chartValues(tool.surveillance_functions).forEach(x=>functions.push(x))});const ownership=[],profileByTool=new Map(p2.filter(item=>item._tool_id).map(item=>[String(item._tool_id),item])),profileByName=new Map(p2.map(item=>[String(item.official_name).trim().toLocaleLowerCase(),item])),matchedProfiles=new Set();tools.forEach(tool=>{const assessment=profileByTool.get(String(tool._id||''))||profileByName.get(String(tool.inventory_name).trim().toLocaleLowerCase()),values=chartValues(assessment?.ownership_institution);if(assessment)matchedProfiles.add(assessment);(values.length?values:chartValues(tool.unit_responsible)).forEach(value=>ownership.push(value))});p2.filter(item=>!matchedProfiles.has(item)).forEach(item=>chartValues(item.ownership_institution).forEach(value=>ownership.push(value)));const api=counts(p2.map(a=>a.api_available||'Not recorded'));$('#portfolio-metrics').innerHTML=[[tools.length,'Systems inventoried'],[p2.length,'Systems assessed'],[new Set(functions).size,'Functions covered'],[p2.filter(a=>String(a.api_available).toLowerCase()==='yes').length,'Systems with API']].map(([value,label])=>`<article class="metric card"><strong>${value}</strong><span>${label}</span></article>`).join('');chartFromCounts('#system-type-chart',counts(typeValues));chartFromCounts('#function-chart',counts(functions));chartFromCounts('#ownership-chart',counts(ownership));chartFromCounts('#api-chart',api)}
function parseAsciiTable(lines,start){const rows=[];let i=start;while(i<lines.length&&lines[i].trim().startsWith('|')){const cells=lines[i].trim().slice(1,-1).split('|').map(x=>x.trim());if(!cells.every(x=>/^[-: ]+$/.test(x)))rows.push(cells);i++}if(!rows.length)return{html:'',next:start+1};const head=rows.shift()||[],merged=[];rows.forEach(row=>{if(row.every(x=>!x))return;const continuation=!row[0]&&merged.length;if(continuation){row.forEach((value,index)=>{if(value)merged.at(-1)[index]=[merged.at(-1)[index],value].filter(Boolean).join(' ')})}else merged.push(row)});return{html:`<div class="report-table"><table><thead><tr>${head.map(x=>`<th>${escapeHtml(x)}</th>`).join('')}</tr></thead><tbody>${merged.map(row=>`<tr>${row.map(x=>`<td>${escapeHtml(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`,next:i}}
function reportHtml(text){const lines=String(text||'').replace(/\r/g,'').split('\n'),major=new Set(['Executive Summary','Surveillance System Profiling: Summary Report','Data completeness by system','System by function support','Overview of the HIS Inventory','System Distribution by Data Type','Distribution of Surveillance Functions','Integration Status','Summary of Findings','Recommendations','Assessment completeness','Domain capability scores','Identified gaps and risks','Strengths to retain','Prioritised recommendations','Action plan','Data-quality and consistency flags']),domains=new Set(state.data?.domains?.map(d=>d.name)||[]);let html='<div class="web-report">',open=false,list=false;const closeList=()=>{if(list){html+='</ul>';list=false}},closeSection=()=>{closeList();if(open)html+='</section>';open=false};for(let i=0;i<lines.length;){const line=lines[i].trim();if(!line){closeList();i++;continue}if(i===0){html+=`<header class="report-hero"><h2>${escapeHtml(line)}</h2>`;let meta=[];i++;while(i<lines.length&&/^(Country|Reporting Period):/.test(lines[i].trim())){meta.push(lines[i].trim());i++}html+=`<div class="report-meta-grid">${meta.map(x=>`<span class="report-meta-chip">${escapeHtml(x)}</span>`).join('')}</div></header>`;continue}if(line.startsWith('|')){closeList();const table=parseAsciiTable(lines,i);html+=table.html;i=table.next;continue}if(/^(Profiling|Gap Analysis:)/.test(line)){closeSection();html+=`<section class="report-section phase-section"><h2>${escapeHtml(line)}</h2>`;open=true;i++;continue}if(major.has(line)||domains.has(line)){closeSection();html+=`<section class="report-section"><h3>${escapeHtml(line)}</h3>`;open=true;i++;continue}if(line==='Africa CDC Gap Analysis'){i++;continue}if(/^[-•]\s+/.test(line)){if(!open){html+='<section class="report-section">';open=true}if(!list){html+='<ul>';list=true}html+=`<li>${escapeHtml(line.replace(/^[-•]\s+/,''))}</li>`;i++;continue}closeList();if(!open){html+='<section class="report-section">';open=true}const labelled=line.match(/^(Overview|Key capabilities|Main gaps and challenges|Reported priority actions|Data validation):\s*(.*)$/);if(labelled)html+=`<p><strong>${escapeHtml(labelled[1])}:</strong> ${escapeHtml(labelled[2])}</p>`;else if(/^(Gaps|Recommendations):$/.test(line))html+=`<h3>${escapeHtml(line)}</h3>`;else if(/^Assigned group:/.test(line))html+=`<p class="report-meta-chip">${escapeHtml(line)}</p>`;else html+=`<p>${escapeHtml(line)}</p>`;i++}closeSection();return html+'</div>'}
