async function createNewAssessment(){const button=$('#create-assessment');try{const country=canonicalCountry($('#assessment-start-country').value),period=$('#assessment-start-period').value;if(!reportingPeriods.includes(period))throw new Error('Select a reporting period from the list');button.disabled=true;button.textContent='Creating...';let result;try{result=await api('/api/projects/new',{method:'POST',body:JSON.stringify({country_name:country,reporting_period:period})})}catch(error){if(!/already exists/i.test(error.message)||!confirm(`${country} (${period}) already exists. Do you want to open the existing assessment and update its information?`))throw error;button.textContent='Opening...';result=await api('/api/projects/new',{method:'POST',body:JSON.stringify({country_name:country,reporting_period:period,open_existing:true})})}state.workspaceSelected=true;state.workspaceSource=result?.opened_existing?(result.existing_source||'redcap'):'new';state.inventoryIndex=0;state.phase2Index=0;state.inventoryGroupId=null;state.profilingGroupId=null;state.groupId=null;state.domainId=null;await loadState(false);$('#assessment-start-country').value='';setPeriodValue($('#assessment-start-period'),defaultReportingPeriod);switchView('phase1');window.scrollTo({top:0,behavior:'smooth'});toast(result?.opened_existing?`Opened ${country} (${period}) for updating`:`Created a blank assessment for ${country} (${period})`)}catch(error){if(!/already exists/i.test(error.message)){toast(error.message);alert(error.message)}}finally{button.disabled=false;button.textContent='Add new data'}}
document.addEventListener('DOMContentLoaded',()=>{$('#create-assessment').onclick=createNewAssessment;$('#assessment-start-country').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();createNewAssessment()}}});
document.addEventListener('DOMContentLoaded',()=>{$('#create-application-user').onclick=createApplicationUser;$('#refresh-application-users').onclick=renderApplicationUsers;$('#application-user-username').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();createApplicationUser()}}});
async function downloadLatestAssistantWord(){const messages=$$('.assistant-message-row.assistant .assistant-message').filter(item=>!item.closest('#assistant-thinking')),latest=messages.at(-1);if(!latest){toast('Generate an assistant response first');return}const copy=latest.cloneNode(true);copy.querySelector('.message-role')?.remove();const answer=copy.textContent.trim();if(!answer||/^Hello\. I can help/i.test(answer)){toast('Generate an assistant response first');return}const button=$('#download-assistant-word');try{button.disabled=true;button.textContent='Preparing Word...';const country=canonicalCountry($('#analysis-country').value),period=$('#analysis-period').value,response=await fetch('/api/assistant/docx',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({answer,title:'Report Assistant Analysis',country_name:country,reporting_period:period})});if(!response.ok){const error=await response.json().catch(()=>({}));throw new Error(error.error||'Could not create Word document')}const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`Africa_CDC_${country.replaceAll(' ','_')}_Assistant_Analysis.docx`;document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);toast('Assistant response downloaded in Word')}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='Download latest response in Word'}}
document.addEventListener('DOMContentLoaded',()=>{$('#download-assistant-word').onclick=downloadLatestAssistantWord});
function portfolioChartSeries(profile=state.analysisProfile){const tools=(profile?.phase1?.tools||[]).filter(item=>item.inventory_name?.trim()),profiles=(profile?.phase2||[]).filter(item=>item.official_name?.trim()),types=[],functions=[],owners=[];tools.forEach(tool=>{types.push(...chartValues(tool.system_type));functions.push(...chartValues(tool.surveillance_functions));owners.push(...chartValues(tool.unit_responsible))});return[{title:'System portfolio by type',data:counts(types)},{title:'Surveillance function coverage',data:counts(functions)},{title:'Responsible units',data:counts(owners)},{title:'API availability',data:counts(profiles.map(item=>item.api_available||'Not recorded'))}]}
function drawPortfolioChartsCanvas(){const canvas=document.createElement('canvas');canvas.width=1600;canvas.height=1100;const ctx=canvas.getContext('2d'),series=portfolioChartSeries(),colors=['#176b45','#c28d20','#7d1c2c','#5f8c35','#126d75'];ctx.fillStyle='#f7faf8';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#0b2545';ctx.font='bold 30px Segoe UI';ctx.fillText(`${$('#analysis-country').value} Surveillance Systems Charts`,55,55);ctx.font='18px Segoe UI';ctx.fillStyle='#50675b';ctx.fillText($('#analysis-period').value,55,84);series.forEach((chart,chartIndex)=>{const x=45+(chartIndex%2)*780,y=120+Math.floor(chartIndex/2)*475,w=730,h=430,entries=Object.entries(chart.data).sort((a,b)=>b[1]-a[1]).slice(0,12),max=Math.max(1,...entries.map(item=>item[1]));ctx.fillStyle='#fff';ctx.strokeStyle='#c8d8ce';ctx.lineWidth=2;ctx.fillRect(x,y,w,h);ctx.strokeRect(x,y,w,h);ctx.fillStyle='#0b2545';ctx.font='bold 22px Segoe UI';ctx.fillText(chart.title,x+25,y+38);const rowHeight=Math.min(31,340/Math.max(1,entries.length));entries.forEach(([label,value],index)=>{const rowY=y+70+index*rowHeight,short=label.length>29?`${label.slice(0,27)}...`:label;ctx.font='14px Segoe UI';ctx.fillStyle='#243b30';ctx.fillText(short,x+25,rowY+15);ctx.fillStyle='#e3ece6';ctx.fillRect(x+265,rowY,390,rowHeight-8);ctx.fillStyle=colors[index%colors.length];ctx.fillRect(x+265,rowY,Math.max(3,390*value/max),rowHeight-8);ctx.fillStyle='#0b2545';ctx.font='bold 14px Segoe UI';ctx.fillText(String(value),x+670,rowY+15)});if(!entries.length){ctx.fillStyle='#64776d';ctx.font='16px Segoe UI';ctx.fillText('No recorded data',x+25,y+85)}});return canvas}
function downloadPortfolioChartsPng(){if(!state.analysisProfile){toast('Generate a report first');return}const canvas=drawPortfolioChartsCanvas(),link=document.createElement('a'),country=canonicalCountry($('#analysis-country').value);link.href=canvas.toDataURL('image/png');link.download=`Africa_CDC_${country.replaceAll(' ','_')}_Charts.png`;document.body.appendChild(link);link.click();link.remove();toast('Charts downloaded as PNG')}
function showChartsFromAssistant(){if(!state.analysisProfile){toast('Generate a report first');return}$('#full-report').classList.add('hidden');$('#graph-output').classList.remove('hidden');renderPortfolioDashboard(state.analysisProfile);$('#show-summary').className='button secondary';$('#show-graphs').className='button primary';let controls=$('#assistant-chart-controls');if(!controls){$('#graph-output').insertAdjacentHTML('afterbegin','<div id="assistant-chart-controls" class="button-row"><button id="download-charts-png" class="button secondary" type="button">Download charts as PNG</button></div>');controls=$('#assistant-chart-controls');$('#download-charts-png').onclick=downloadPortfolioChartsPng}const messages=$('#assistant-messages');messages.insertAdjacentHTML('beforeend','<div class="assistant-message-row assistant"><span class="message-avatar" aria-hidden="true">A</span><div class="assistant-message assistant"><span class="message-role">Report assistant · Local charts</span>I generated the available charts from the report data loaded in the app. Use Download charts as PNG to save them.</div></div>');messages.scrollTop=messages.scrollHeight;toggleReportAssistant(false);toast('Charts generated from the current report')}
function isChartAssistantPrompt(value){return /\b(generate|create|make|show|plot|draw)\b.*\b(chart|charts|graph|graphs|visuali[sz]ation)\b|\b(chart|charts|graph|graphs)\b.*\b(report|table|data)\b/i.test(String(value||''))}
document.addEventListener('DOMContentLoaded',()=>{$('#ask-report-assistant').addEventListener('click',event=>{const value=$('#assistant-question').value;if(!isChartAssistantPrompt(value))return;event.preventDefault();event.stopImmediatePropagation();$('#assistant-question').value='';showChartsFromAssistant()},{capture:true});$('#assistant-question').addEventListener('keydown',event=>{if(event.key!=='Enter'||event.shiftKey||!isChartAssistantPrompt(event.currentTarget.value))return;event.preventDefault();event.stopImmediatePropagation();event.currentTarget.value='';showChartsFromAssistant()},{capture:true})});
async function waitForLocalServer(timeoutMs=90000){const started=Date.now();while(Date.now()-started<timeoutMs){try{const response=await fetch('/health',{cache:'no-store'});if(response.ok)return true}catch{}await new Promise(resolve=>setTimeout(resolve,2000))}return false}
async function streamAssistantAnswer(payload,onDelta){async function attempt(){const response=await fetch('/api/assistant/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok){const error=await response.json().catch(()=>({}));throw new Error(error.error||`Local AI request failed (${response.status})`)}if(!response.body)throw new Error('Streaming is not supported by this browser');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='',answer='';while(true){const{value,done}=await reader.read();buffer+=decoder.decode(value||new Uint8Array(),{stream:!done});const lines=buffer.split('\n');buffer=lines.pop()||'';for(const line of lines){if(!line.trim())continue;const packet=JSON.parse(line);if(packet.coverage_check)state.recommendationAudit=packet.coverage_check;if(packet.delta){answer+=packet.delta;onDelta(answer)}}if(done)break}if(buffer.trim()){const packet=JSON.parse(buffer);if(packet.coverage_check)state.recommendationAudit=packet.coverage_check;if(packet.delta){answer+=packet.delta;onDelta(answer)}}return answer.trim()}try{return await attempt()}catch(error){if(!/failed to fetch|networkerror|load failed|connection|fetch/i.test(String(error?.message||error)))throw error;toast('Local server connection lost - waiting to reconnect');const recovered=await waitForLocalServer();if(!recovered)throw new Error('The local application server is not running. Restart the assessment app, refresh this page, and try again.');onDelta('');toast('Connection restored - restarting the analysis');return attempt()}}
const baseSetReportAssistantEnabled=setReportAssistantEnabled;setReportAssistantEnabled=function(enabled){baseSetReportAssistantEnabled(enabled);if(!enabled)return;api('/api/assistant/status').then(status=>{const label=$('.assistant-identity p');if(label)label.innerHTML=`<span class="assistant-status-dot"></span>${status.online?'Online AI':'Local AI'} · ${escapeHtml(status.model)}${status.online?' · Generated report only':''}`;state.assistantModelAvailable=Boolean(status.available)}).catch(()=>{})}
async function loadAssistantProviderSettings(){try{const status=await api('/api/assistant/status');$('#assistant-provider').value=status.provider||'local';$('#assistant-provider-status').textContent=status.online?`Online provider: ${status.model}. API key configured: ${status.configured?'Yes':'No'}.`:`Local provider: ${status.model}. Available: ${status.available?'Yes':'No'}.`}catch(error){$('#assistant-provider-status').textContent=error.message}}
async function saveAssistantProvider(){const provider=$('#assistant-provider').value,approved=$('#assistant-online-approved').checked;try{const status=await api('/api/assistant/provider',{method:'POST',body:JSON.stringify({provider,approved})});$('#assistant-online-approved').checked=false;$('#assistant-provider-status').textContent=`Saved: ${status.online?'Online AI':'Local AI'} · ${status.model}`;toast('Assistant provider updated')}catch(error){toast(error.message);$('#assistant-provider-status').textContent=error.message}}
async function testAssistantProvider(){const button=$('#test-assistant-provider');try{button.disabled=true;button.textContent='Testing...';const result=await api('/api/assistant/provider/test',{method:'POST',body:'{}'});$('#assistant-provider-status').textContent=result.ok?`Connection successful: ${result.provider||'local'} · ${result.model}`:(result.error||'Provider test failed');toast(result.ok?'Provider connection successful':'Provider test failed')}catch(error){toast(error.message);$('#assistant-provider-status').textContent=error.message}finally{button.disabled=false;button.textContent='Test provider'}}
document.addEventListener('DOMContentLoaded',()=>{$('#save-assistant-provider').onclick=saveAssistantProvider;$('#test-assistant-provider').onclick=testAssistantProvider;$$('[data-view="users"]').forEach(button=>button.addEventListener('click',()=>setTimeout(loadAssistantProviderSettings,0)))});
window.addEventListener('unhandledrejection',event=>{const message=event.reason?.message||'The operation failed';event.preventDefault();toast(message);if(/REDCap did not accept|REDCap save failed/i.test(message))alert(message)});
